  b
FROM t
WHERE x = 1;

UPDATE t SET a = 1
WHERE id = 2;

CREATE PROCEDURE p()
BEGIN
  SELECT 1;
  IF 1 THEN SELECT 2; END IF;
END;
CALL p();

expect:
