BEGIN
  SELECT 1;
  IF 1 THEN SELECT 2; END IF;
END;

cases.sql:
CREATE DEFINER=`root`@`%` PROCEDURE p()
BEGIN
  l: LOOP LEAVE l; END LOOP;
  CASE WHEN 1 THEN SELECT 1; ELSE SELECT 2; END CASE;
  SELECT CASE WHEN 1 THEN 2 END;
END;
SELECT 3;

expect:
CREATE DEFINER=`root`@`%` PROCEDURE p()
BEGIN
  l: LOOP LEAVE l; END LOOP;
  CASE WHEN 1 THEN SELECT 1; ELSE SELECT 2; END CASE;
  SELECT CASE WHEN 1 THEN 2 END;
